function subtractProductAndSum(n) {
  // Read the digits from the number's text instead of using arithmetic.
  const digits = String(n).split('').map(Number);
  return digits.reduce((a, b) => a * b, 1) - digits.reduce((a, b) => a + b, 0);
}

