function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') return [10000 + pick(90001)];
  const length = 1 + pick(5);
  // Sometimes avoid zero digits so the product is not simply 0.
  const noZero = rand() < 0.6;
  let n = 1 + pick(9);
  for (let i = 1; i < length; i++) n = n * 10 + (noZero ? 1 + pick(9) : pick(10));
  return [n];
}
